"""Naive independent re-implementation of PROTOCOL.md v3 for cross-checking.

Deliberately slow and literal: it re-reads the specification rather than the
submission's modules, so coding mistakes rarely coincide.
"""
import base64, collections, hashlib, ipaddress, plistlib, struct, sys
sys.path.insert(0, '/workspace/deps')

DOC = ipaddress.IPv6Network('2001:db8::/32')
COLS = ['type','id','revision','published','op','lease','event','probe','target',
        'responder','result','service','attempt','payload']


class Bad(Exception):
    pass


def ident(value):
    return isinstance(value, str) and 1 <= len(value) <= 24 and all(
        c.isascii() and (c.isalnum() or c in '_-') for c in value)


def num(text, high):
    if not (isinstance(text, str) and 1 <= len(text) <= 16 and all(c in '0123456789' for c in text)):
        raise Bad('digits')
    value = int(text)
    if value > high:
        raise Bad('range')
    return value


def addr(text):
    try:
        value = ipaddress.IPv6Address(text)
    except Exception:
        raise Bad('address')
    if value not in DOC:
        raise Bad('doc')
    return int(value)


def target(i):
    return str(ipaddress.IPv6Address(i))


def plan_targets(job):
    manifest = []
    probes = collections.defaultdict(dict)
    lows = collections.defaultdict(set)
    for lease in sorted(job['leases'], key=lambda x: x['id']):
        net = ipaddress.IPv6Network(lease['prefix'], strict=True)
        base = int(net.network_address)
        for subnet in sorted(lease['subnets']):
            n64 = base + (subnet << 64)
            text = '%s/64' % ipaddress.IPv6Network((n64, 64)).network_address.compressed
            digest = hashlib.sha256(('\n'.join([job['seed'], lease['id'], text])).encode()).digest()
            canary = int.from_bytes(digest[:8], 'big') | (1 << 63)
            manifest.append((lease['id'], '%d/c' % subnet, n64 + canary))
            probes[lease['id']]['%d/c' % subnet] = (n64 + canary, True)
            for i in range(1, lease['low_count'] + 1):
                manifest.append((lease['id'], '%d/i%d' % (subnet, i), n64 + i))
                probes[lease['id']]['%d/i%d' % (subnet, i)] = (n64 + i, False)
                lows[lease['id']].add(n64 + i)
    return [{'lease': a, 'probe': b, 'target': target(c)} for a, b, c in manifest], probes, lows


def parse_row(values, job, probes):
    if len(values) != 14:
        raise Bad('count')
    kind, name, revision, published, op, lease, event, probe, tgt, resp, result, service, attempt, payload = values
    if kind not in ('icmp', 'app') or not ident(name):
        raise Bad('type/id')
    rev = num(revision, 10 ** 9)
    pub = num(published, 10 ** 12)
    if op == 'delete':
        if values[5:] != [''] * 9:
            raise Bad('delete tail')
        return (('icmp' if kind == 'icmp' else 'app', name), rev, pub, ('D',), None)
    if op != 'put':
        raise Bad('op')
    table = {l['id']: l for l in job['leases']}
    if lease not in table:
        raise Bad('lease')
    ev = num(event, 10 ** 12)
    if not (table[lease]['start'] <= ev < table[lease]['end']) or ev > pub:
        raise Bad('event')
    t = addr(tgt)
    if kind == 'icmp':
        if service or attempt or payload:
            raise Bad('icmp extras')
        if probe not in probes[lease]:
            raise Bad('probe')
        planned, canary = probes[lease][probe]
        if t != planned:
            raise Bad('target mismatch')
        if result not in ('echo', 'error', 'timeout'):
            raise Bad('result')
        if result == 'timeout':
            if resp:
                raise Bad('timeout responder')
            r = None
        else:
            r = addr(resp)
        content = ('I', lease, ev, probe, t, r, result, canary)
        return ((kind, name), rev, pub, content, None)
    kinds = {s['id']: s['kind'] for s in job['services']}
    if service not in kinds:
        raise Bad('service')
    if probe or resp:
        raise Bad('app empties')
    if result not in ('open', 'closed', 'timeout'):
        raise Bad('app result')
    att = num(attempt, 10 ** 6)
    try:
        data = base64.b64decode(payload.encode('ascii'), validate=True)
    except Exception:
        raise Bad('payload base64')
    if len(data) > 65536:
        raise Bad('payload size')
    if result in ('closed', 'timeout') and data:
        raise Bad('payload must be empty')
    if kinds[service] == 'tcp' and data:
        raise Bad('tcp payload')
    content = ('A', lease, ev, t, service, att, result, data)
    return ((kind, name), rev, pub, content, None)


def adb_sig(data):
    if len(data) < 24:
        raise Bad('adb short')
    command, arg0, arg1, length, check, magic = struct.unpack('<6I', data[:24])
    if command ^ magic != 0xffffffff or length > 65535 or len(data) != 24 + length:
        raise Bad('adb framing')
    body = data[24:]
    if (sum(body) & 0xffffffff) != check:
        raise Bad('adb checksum')
    if command == 0x4e584e43:
        banner = body.decode('utf-8')
        return ('CNXN', '%d.%d.%d' % ((arg0 >> 16) & 255, (arg0 >> 8) & 255, arg0 & 255), banner)
    if command == 0x48545541:
        return ('AUTH', arg0, arg1, bytes(body))
    raise Bad('adb command')


def sync_sig(data):
    if len(data) < 8:
        raise Bad('sync short')
    values = []
    at = 0
    for want in ('ProductVersion', 'ProductName'):
        size = struct.unpack('>I', data[at:at + 4])[0]
        at += 4
        if not 1 <= size <= 65532 or at + size > len(data):
            raise Bad('sync frame')
        obj = plistlib.loads(data[at:at + size])
        at += size
        if not isinstance(obj, dict) or set(obj) != {'Key', 'Request', 'Value'}:
            raise Bad('sync keys')
        if obj['Key'] != want or obj['Request'] != 'GetValue':
            raise Bad('sync content')
        if not isinstance(obj['Value'], str) or not obj['Value']:
            raise Bad('sync value')
        values.append(obj['Value'])
    if at != len(data):
        raise Bad('sync trailing')
    return ('sync', values[0], values[1])


def signature(kind, data):
    try:
        if kind == 'tcp':
            return ('tcp',) if not data else None
        if kind == 'adb':
            return adb_sig(data)
        return sync_sig(data)
    except Exception:
        return None


def visible(rows, moment):
    """Return (live contents, deleted, conflicts) using the revision rules."""
    by_ident = collections.defaultdict(list)
    for identity, rev, pub, content, _ in rows:
        if pub <= moment:
            by_ident[identity].append((rev, content))
    live = []
    deleted = conflicts = 0
    for identity, items in sorted(by_ident.items(), key=lambda x: str(x[0])):
        top = max(r for r, _ in items)
        contents = set(c for r, c in items if r == top)
        if len(contents) > 1:
            conflicts += 1
        elif list(contents)[0] == ('D',):
            deleted += 1
        else:
            live.append(list(contents)[0])
    return {'live': len(live), 'deleted': deleted, 'conflict': conflicts}, live


def census(job, rows, probes, lows):
    services = {s['id']: s['kind'] for s in job['services']}
    order = sorted(services)
    lease_order = sorted(l['id'] for l in job['leases'])
    table = {l['id']: l for l in job['leases']}
    snapshots = []
    for moment in sorted(job['queries']):
        counts, live = visible(rows, moment)
        internal = {l: set() for l in lease_order}
        external = {l: set() for l in lease_order}
        win = {l: {} for l in lease_order}
        wout = {l: {} for l in lease_order}
        aliased = set()
        apps = []
        for content in live:
            if content[0] == 'I':
                _, lease, ev, probe, t, r, result, canary = content
                if canary:
                    if result == 'echo' and r == t:
                        aliased.add(lease)
                elif result != 'timeout':
                    if result == 'echo' and r == t:
                        internal[lease].add(r)
                        win[lease][r] = min(win[lease].get(r, ev), ev)
                    else:
                        external[lease].add(r)
                        wout[lease][r] = min(wout[lease].get(r, ev), ev)
            else:
                apps.append(content)
        state, clean_i, clean_e, clash = {}, {}, {}, {}
        for lease in lease_order:
            row = table[lease]
            if not (row['start'] <= moment < row['end']):
                state[lease] = 'inactive'
                clean_i[lease] = clean_e[lease] = clash[lease] = set()
                continue
            c = internal[lease] & external[lease]
            clash[lease] = set(c)
            if lease in aliased:
                state[lease] = 'alias'
                clean_i[lease] = clean_e[lease] = set()
            elif c:
                state[lease] = 'conflict'
                clean_i[lease] = clean_e[lease] = set()
            else:
                state[lease] = 'usable'
                clean_i[lease] = set(internal[lease])
                clean_e[lease] = set(external[lease])
        groups = collections.defaultdict(list)
        unbound = 0
        for content in apps:
            _, lease, ev, t, service, att, result, data = content
            role = None
            if state[lease] == 'usable':
                if t in clean_i[lease]:
                    role = ('internal', win[lease].get(t))
                elif t in clean_e[lease]:
                    role = ('external', wout[lease].get(t))
            if role is None or role[1] is None or role[1] > ev:
                unbound += 1
                continue
            groups[(lease, t, service)].append((att, result, data, role[0]))
        report = {l: {s: {'internal_open': set(), 'internal_closed': set(),
                          'external_open': set(), 'external_closed': set(),
                          'protocol_errors': 0} for s in order} for l in lease_order}
        for (lease, t, service), items in groups.items():
            top = max(a for a, _, _, _ in items)
            latest = [x for x in items if x[0] == top]
            closed = [x for x in latest if x[1] == 'closed']
            timeouts = [x for x in latest if x[1] == 'timeout']
            opens = [x for x in latest if x[1] == 'open']
            sigs = [signature(services[service], x[2]) for x in opens]
            bad = sum(1 for s in sigs if s is None)
            report[lease][service]['protocol_errors'] += bad
            role = latest[0][3]
            if len(closed) == len(latest):
                status = 'closed'
            elif len(opens) == len(latest) and bad == 0 and len(set(sigs)) == 1:
                status = 'open'
            else:
                status = None
            if status:
                report[lease][service][role + '_' + status].add(t)
        leases_out = []
        for lease in lease_order:
            if state[lease] == 'usable':
                unresolved = lows.get(lease, set()) - clean_i[lease] - clean_e[lease]
            elif state[lease] == 'inactive':
                unresolved = set()
            else:
                unresolved = set(lows.get(lease, set()))
            entries = []
            for service in order:
                rep = report[lease][service]
                only = set()
                if clean_e[lease] and all(t in rep['external_closed'] for t in clean_e[lease]):
                    only = set(rep['internal_open'])
                entries.append({'id': service,
                                'internal_open': [target(x) for x in sorted(rep['internal_open'])],
                                'internal_closed': [target(x) for x in sorted(rep['internal_closed'])],
                                'external_open': [target(x) for x in sorted(rep['external_open'])],
                                'external_closed': [target(x) for x in sorted(rep['external_closed'])],
                                'internal_only': [target(x) for x in sorted(only)],
                                'protocol_errors': rep['protocol_errors']})
            leases_out.append({'lease': lease, 'state': state[lease],
                               'conflicts': [target(x) for x in sorted(clash[lease])],
                               'internal': [target(x) for x in sorted(clean_i[lease])],
                               'external': [target(x) for x in sorted(clean_e[lease])],
                               'unresolved': [target(x) for x in sorted(unresolved)],
                               'services': entries})
        snapshots.append({'at': moment, 'ledger': counts, 'unbound_applications': unbound,
                          'leases': leases_out})
    return snapshots


def activity(job, snapshots):
    by_moment = {s['at']: s for s in snapshots}
    out = {}
    for request in job['requests']:
        snap = by_moment[request['at']]
        lease = next(x for x in snap['leases'] if x['lease'] == request['lease'])
        ok = False
        if lease['state'] == 'usable' and request['target'] in lease['internal']:
            entry = next(x for x in lease['services'] if x['id'] == request['service'])
            ok = request['target'] not in entry['internal_open'] and \
                 request['target'] not in entry['internal_closed']
        out[request['id']] = ok
    return out


def allowed(job, snap_index, active):
    table = {l['id']: l for l in job['leases']}
    pairs = []
    for request in job['requests']:
        if not active[request['id']]:
            continue
        for offer in job['offers']:
            if request['id'] not in offer['requests']:
                continue
            if request['service'] != offer['service']:
                continue
            if not (request['at'] <= offer['time'] < table[request['lease']]['end']):
                continue
            value = addr(request['target'])
            net = ipaddress.IPv6Network(offer['prefix'])
            if value not in net:
                continue
            pairs.append((request['id'], offer['id']))
    return pairs


def optimum(job, active, pairs):
    """Brute-force maximum cardinality / minimum cost over tiny instances."""
    requests = [r['id'] for r in job['requests'] if active[r['id']]]
    options = {r: [o for (x, o) in pairs if x == r] for r in requests}
    requests = [r for r in requests if options[r]]
    offers = {o['id']: o for o in job['offers']}
    rq = {q['id']: q for q in job['request_quotas']}
    oq = {q['id']: q for q in job['offer_quotas']}

    def ancestors(node, table):
        out = []
        while node is not None:
            out.append(node)
            node = table[node]['parent']
        return out

    best = None
    def walk(index, chosen):
        nonlocal best
        if index == len(requests):
            used_r = collections.Counter()
            used_o = collections.Counter()
            cost = 0
            for r, o in chosen.items():
                used_o[o] += 1
                cost += offers[o]['cost']
                for node in ancestors(next(x for x in job['requests'] if x['id'] == r)['group'], rq):
                    used_r[node] += 1
            for node, count in used_r.items():
                if count > rq[node]['capacity']:
                    return
            for node, count in used_o.items():
                pass
            for o, count in used_o.items():
                if count > offers[o]['capacity']:
                    return
                for node in ancestors(offers[o]['group'], oq):
                    pass
            used_o2 = collections.Counter()
            for r, o in chosen.items():
                for node in ancestors(offers[o]['group'], oq):
                    used_o2[node] += 1
            for node, count in used_o2.items():
                if count > oq[node]['capacity']:
                    return
            key = (-len(chosen), cost)
            if best is None or key < best[0]:
                best = (key, dict(chosen))
            return
        request = requests[index]
        walk(index + 1, chosen)
        for offer in options[request]:
            chosen[request] = offer
            walk(index + 1, chosen)
            del chosen[request]
    if len(requests) <= 9:
        walk(0, {})
    if best is None:
        best = ((0, 0), {})
    return -best[0][0], best[0][1], best[1]


def run(job):
    manifest, probes, lows = plan_targets(job)
    return manifest, probes, lows
